package deploy

import (
	"bytes"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"text/tabwriter"
)

// PlaceholderPrefix marks a value only a human can supply — a connection string,
// a host, a credential, a cron schedule.
//
// The spelling is load-bearing. It contains no YAML metacharacter, so it is a
// legal unquoted plain scalar in every position including the start of a value;
// it is legal inside a URL; the hint after the prefix says what to supply, so a
// grep hit is self-explanatory; and one regexp finds every instance.
const PlaceholderPrefix = "REPLACE-ME-"

// A hint of at least one character, ending in an alphanumeric so trailing
// punctuation in prose ("set REPLACE-ME-SFTP-HOST, then …") is not swallowed.
var placeholderPattern = regexp.MustCompile(`REPLACE-ME-[A-Z0-9-]*[A-Z0-9]`)

// Placeholder is one unfilled value in one line of one file.
type Placeholder struct {
	// File is relative to the scanned root, slash-separated.
	File string `json:"file"`
	Line int    `json:"line"`

	// Token is the whole marker including its hint, so a reader knows what the
	// value is without opening the file.
	Token string `json:"token"`
}

// scanPlaceholders reports every placeholder in rels, which are slash-separated
// paths relative to root.
//
// A path that does not exist is skipped rather than an error: the same function
// serves --plan, where it scans a staging directory, and a re-run, where it scans
// the committed tree and some of rels were never written.
//
// An unpinned image tag is deliberately *not* a placeholder. Pinning is
// intropy deploy's job, and inviting someone to hand-edit an image tag would
// undo the digest discipline the rest of this package exists to enforce.
func scanPlaceholders(root string, rels []string) ([]Placeholder, error) {
	var out []Placeholder
	for _, rel := range rels {
		data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
		if err != nil {
			if errorsIsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("scan %s for placeholders: %w", rel, err)
		}
		// A binary file cannot carry a placeholder a human would edit, and
		// reporting a line number in one would be meaningless.
		if bytes.IndexByte(data, 0) >= 0 {
			continue
		}
		for i, line := range strings.Split(string(data), "\n") {
			for _, token := range placeholderPattern.FindAllString(line, -1) {
				out = append(out, Placeholder{File: rel, Line: i + 1, Token: token})
			}
		}
	}

	slices.SortFunc(out, func(a, b Placeholder) int {
		if c := strings.Compare(a.File, b.File); c != 0 {
			return c
		}
		if a.Line != b.Line {
			return a.Line - b.Line
		}
		return strings.Compare(a.Token, b.Token)
	})
	return out, nil
}

func errorsIsNotExist(err error) bool {
	return os.IsNotExist(err) || err == fs.ErrNotExist
}

// reportPlaceholders writes the placeholder table and the summary line.
//
// Remaining placeholders are the expected outcome, never a failure: complete
// manifests are explicitly not the goal, and the command's value is that the
// remaining work is now a bounded, greppable list.
func reportPlaceholders(out output, found []Placeholder) {
	if len(found) == 0 {
		fmt.Fprintln(out.Stdout, "\nno placeholders left to fill in")
		return
	}

	fmt.Fprintf(out.Stdout, "\n%s\n", summarisePlaceholders(found))
	tw := tabwriter.NewWriter(out.Stdout, 0, 0, 2, ' ', 0)
	for _, p := range found {
		fmt.Fprintf(tw, "  %s:%d\t%s\n", p.File, p.Line, p.Token)
	}
	_ = tw.Flush()
	fmt.Fprintf(out.Stdout, "\nimage tags are not placeholders: 'intropy deploy' pins digests, so leave them alone\n")
}

func summarisePlaceholders(found []Placeholder) string {
	files := map[string]bool{}
	for _, p := range found {
		files[p.File] = true
	}
	return fmt.Sprintf("%d placeholder%s to fill in across %d file%s:",
		len(found), plural(len(found)), len(files), plural(len(files)))
}

package deploy

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// destTree is the boundary a scaffold may write inside: the GitOps checkout, and
// nothing else on the machine.
//
// Every read and write goes through os.Root, so a path that leaves the directory
// is refused by the kernel rather than by our own string handling. That alone is
// not enough, for two reasons:
//
//   - os.Root still follows a symlink whose target stays inside the root, and
//     .git/hooks is inside the root — a link there turns a manifest write into
//     code that runs on the next commit;
//   - the paths come from a GitOps repository and from --domain/--system, neither
//     of which this CLI controls.
//
// So a symlink on any component of a destination path is a hard refusal. A
// GitOps tree has no legitimate use for one, and following it would mean writing
// somewhere the plan never named.
type destTree struct {
	root *os.Root

	// path is the directory as the user knows it, for messages. os.Root's own
	// errors are relative to the root and read as if the file were at /.
	path string
}

func openDestTree(dir string) (*destTree, error) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", dir, err)
	}
	return &destTree{root: root, path: dir}, nil
}

func (t *destTree) Close() error { return t.root.Close() }

// assertRelIsLocal refuses a repository-relative path that does not stay inside
// the repository.
//
// filepath.IsLocal is the whole check: it rejects an absolute path, an empty one,
// anything that climbs out with .., and the Windows spellings (drive-relative,
// UNC, reserved device names) that a Unix-only rule would miss.
func assertRelIsLocal(rel string) error {
	if rel == "" {
		return errors.New("empty repository-relative path")
	}
	if !filepath.IsLocal(filepath.FromSlash(rel)) {
		return fmt.Errorf("%s is not a path inside the repository", rel)
	}
	return nil
}

// assertWritable reports whether rel may be written, without writing anything.
//
// It is called during classification as well as before the write, so a hostile
// tree is refused before the first byte lands — including under --plan, where
// nothing would be written at all.
func (t *destTree) assertWritable(rel string) error {
	if err := assertRelIsLocal(rel); err != nil {
		return err
	}

	// Top down, leaf last. The order is the point: a parent symlink has to be
	// caught before an Lstat of anything beneath it would traverse it.
	segments := strings.Split(path.Clean(rel), "/")
	for i := range segments {
		prefix := path.Join(segments[:i+1]...)
		leaf := i == len(segments)-1

		info, err := t.root.Lstat(prefix)
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) {
				// Nothing from here down exists yet, so there is nothing left to
				// follow: the write will create it.
				return nil
			}
			return fmt.Errorf("inspect %s: %w", filepath.Join(t.path, filepath.FromSlash(prefix)), err)
		}

		switch {
		case info.Mode()&fs.ModeSymlink != 0:
			return fmt.Errorf("%s is a symlink; refusing to write %s through it, because a symlink on a path this command writes can redirect the write out of the repository",
				filepath.Join(t.path, filepath.FromSlash(prefix)), rel)
		case !leaf && !info.IsDir():
			return fmt.Errorf("%s is not a directory, so %s cannot be written", filepath.Join(t.path, filepath.FromSlash(prefix)), rel)
		case leaf && !info.Mode().IsRegular():
			return fmt.Errorf("%s is not a regular file", filepath.Join(t.path, filepath.FromSlash(prefix)))
		}
	}
	return nil
}

// read returns the file's current contents, reporting fs.ErrNotExist unchanged
// so a caller can tell "not there yet" from a failure to read it.
func (t *destTree) read(rel string) ([]byte, error) {
	return t.root.ReadFile(rel)
}

// write replaces the file at rel.
//
// Remove and create exclusively rather than truncate in place: O_EXCL on a path
// that does not exist cannot follow a link, so the final open is no-follow
// without depending on a platform's O_NOFOLLOW. assertWritable has already
// refused a symlink here, and this makes the write itself not depend on that
// check still holding.
func (t *destTree) write(rel string, data []byte) error {
	if dir := path.Dir(rel); dir != "." {
		if err := t.root.MkdirAll(dir, 0o755); err != nil {
			return fmt.Errorf("create %s: %w", dir, err)
		}
	}
	if err := t.root.Remove(rel); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("replace %s: %w", rel, err)
	}
	f, err := t.root.OpenFile(rel, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return fmt.Errorf("create %s: %w", rel, err)
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		return fmt.Errorf("write %s: %w", rel, err)
	}
	return f.Close()
}

// assertPathSegment refuses a name that is not a single directory or file name.
//
// --domain, --system and a component name from the topology all become tree
// segments. destTree already makes a traversal impossible at the write, but the
// error there names a rendered path; this one names the input that was wrong.
// They also become part of a branch name, where a slash would silently nest a
// ref rather than fail.
func assertPathSegment(what, name string) error {
	switch {
	case name == "":
		return fmt.Errorf("%s is empty", what)
	case name == "." || name == "..":
		return fmt.Errorf("invalid %s %q", what, name)
	case strings.HasPrefix(name, "."):
		return fmt.Errorf("invalid %s %q (must not start with a dot)", what, name)
	case strings.ContainsAny(name, `/\`):
		return fmt.Errorf("invalid %s %q (must be a single path segment)", what, name)
	}
	return nil
}

package kustomize

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"gopkg.in/yaml.v3"
)

// Normalize canonicalises a rendered manifest stream so two renders can be
// compared meaningfully.
//
// Documents are sorted by identity — apiVersion, kind, namespace, name — because
// kustomize's output order is not guaranteed stable across edits, and a
// reordered document would otherwise show up as a large deletion followed by a
// large insertion. Each document is re-encoded through yaml.Node rather than a
// map, which preserves the key order as authored: decoding into map[string]any
// would reorder every key on every render and bury the one line that changed.
func Normalize(manifests []byte) ([]byte, error) {
	return normalize(manifests, false)
}

// NormalizeJSON canonicalises manifests that arrive as one JSON document each,
// which is how ArgoCD's render endpoint returns them.
//
// JSON is valid YAML, so the documents parse without conversion — but yaml.v3
// records the flow style it decoded them from and would re-encode every resource
// onto a single line. The style is therefore cleared, which yields block YAML
// comparable line by line with anything Normalize produces. Key order survives:
// it is the order the JSON carried.
func NormalizeJSON(docs []string) ([]byte, error) {
	return normalize([]byte(strings.Join(docs, "\n---\n")), true)
}

// Identities names the resources in a normalised stream, in stream order.
//
// The name is built from the same apiVersion/kind/namespace/name tuple documents
// are sorted by, so it identifies a resource uniquely and two streams can be
// compared as sets — but it is written to be read, because a caller comparing two
// renders reports the difference to someone.
func Identities(normalized []byte) ([]string, error) {
	docs, err := splitDocuments(normalized, false)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(docs))
	for _, doc := range docs {
		ids = append(ids, doc.name)
	}
	return ids, nil
}

func normalize(manifests []byte, block bool) ([]byte, error) {
	docs, err := splitDocuments(manifests, block)
	if err != nil {
		return nil, err
	}

	// A stable sort keeps documents that share an identity — which is invalid
	// input, but not this function's business to reject — in input order.
	stableSortBy(docs, func(a, b document) bool { return a.key < b.key })

	var out bytes.Buffer
	for i, doc := range docs {
		if i > 0 {
			out.WriteString("---\n")
		}
		out.Write(doc.text)
	}
	return out.Bytes(), nil
}

type document struct {
	// key sorts, name is the same identity written for a person to read.
	key  string
	name string
	text []byte
}

// splitDocuments parses a manifest stream into re-encoded documents. block
// forces block style, for input that was JSON.
func splitDocuments(manifests []byte, block bool) ([]document, error) {
	dec := yaml.NewDecoder(bytes.NewReader(manifests))
	var docs []document
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, fmt.Errorf("parse rendered manifests: %w", err)
		}
		// An empty document (a stray "---") decodes to a zero node.
		if node.Kind == 0 {
			continue
		}
		if block {
			clearFlowStyle(&node)
		}

		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		if err := enc.Encode(&node); err != nil {
			return nil, fmt.Errorf("re-encode rendered manifest: %w", err)
		}
		enc.Close()

		docs = append(docs, document{key: identityOf(&node), name: describeIdentity(&node), text: buf.Bytes()})
	}
	return docs, nil
}

// clearFlowStyle strips the style flags off a node and everything under it, so a
// tree decoded from JSON re-encodes as block YAML rather than as the single line
// it came in on.
func clearFlowStyle(n *yaml.Node) {
	n.Style = 0
	for _, child := range n.Content {
		clearFlowStyle(child)
	}
}

// identityOf builds the sort key from a resource's identity fields. Missing
// fields sort first, which groups malformed documents together rather than
// scattering them.
func identityOf(node *yaml.Node) string {
	root := node
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	apiVersion := mappingValue(root, "apiVersion")
	kind := mappingValue(root, "kind")
	metadata := mappingNode(root, "metadata")
	namespace := mappingValue(metadata, "namespace")
	name := mappingValue(metadata, "name")
	return strings.Join([]string{apiVersion, kind, namespace, name}, "\x00")
}

// describeIdentity writes a resource's identity the way kubectl does, which is
// how anyone reading it already expects to see it named. It is still unique:
// none of kind, namespace or name can contain a space or a slash.
func describeIdentity(node *yaml.Node) string {
	root := node
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	metadata := mappingNode(root, "metadata")
	name := mappingValue(metadata, "name")
	if namespace := mappingValue(metadata, "namespace"); namespace != "" {
		name = namespace + "/" + name
	}
	return mappingValue(root, "kind") + " " + name
}

func mappingNode(node *yaml.Node, key string) *yaml.Node {
	if node == nil || node.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1]
		}
	}
	return nil
}

func mappingValue(node *yaml.Node, key string) string {
	if v := mappingNode(node, key); v != nil && v.Kind == yaml.ScalarNode {
		return v.Value
	}
	return ""
}

// stableSortBy is a small insertion sort: document counts here are in the tens,
// and this keeps the comparison inline and obvious.
func stableSortBy(docs []document, less func(a, b document) bool) {
	for i := 1; i < len(docs); i++ {
		for j := i; j > 0 && less(docs[j], docs[j-1]); j-- {
			docs[j], docs[j-1] = docs[j-1], docs[j]
		}
	}
}

