package main

import (
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/spf13/cobra"
)

type manifestsInspectFlags struct {
	system          string
	templateVersion string
	templateRepo    string
	output          string
}

var manifestsInspectFlagValues = manifestsInspectFlags{output: deploy.OutputPlain}

var manifestsInspectCmd = &cobra.Command{
	Use:   "inspect",
	Short: "Inspect the deployment model derived from a system topology",
	Long: "Read the system topology and scaffold records, resolve the template release, and print the components, " +
		"workloads, connectors, and recorded environment bindings. Nothing is rendered or written, and Git is not touched.",
	Args: cobra.NoArgs,
	RunE: func(cmd *cobra.Command, _ []string) error {
		if err := validateOutputFlag(manifestsInspectFlagValues.output, deploy.OutputPlain, deploy.OutputJSON); err != nil {
			return err
		}
		owner, repo, err := resolveTemplateRepo(manifestsInspectFlagValues.templateRepo)
		if err != nil {
			return err
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		return deploy.InspectManifests(ctx, deploy.InspectManifestOptions{
			System:          manifestsInspectFlagValues.system,
			TemplateVersion: manifestsInspectFlagValues.templateVersion,
			OutputFormat:    manifestsInspectFlagValues.output,
			UserAgent:       "intropy-cli/" + version,
			Stdin:           cmd.InOrStdin(),
			Stdout:          cmd.OutOrStdout(),
			Stderr:          cmd.ErrOrStderr(),
			Owner:           owner,
			Repo:            repo,
		})
	},
}

func init() {
	f := manifestsInspectCmd.Flags()
	f.StringVar(&manifestsInspectFlagValues.system, "system", "", flagUsageManifestSystem)
	f.StringVar(&manifestsInspectFlagValues.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&manifestsInspectFlagValues.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.StringVarP(&manifestsInspectFlagValues.output, "output", "o", deploy.OutputPlain, flagUsageOutput)
	manifestsCmd.AddCommand(manifestsInspectCmd)
}

package main

import (
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/spf13/cobra"
)

type manifestsRenderFlags struct {
	env             string
	system          string
	templateVersion string
	templateRepo    string
	namespace       string
	images          []string
}

var manifestsRenderFlagValues manifestsRenderFlags

var manifestsRenderCmd = &cobra.Command{
	Use:   "render",
	Short: "Render a system's Kubernetes manifests as YAML",
	Long: "Render and validate the complete manifest stream for one environment. For local development, YAML is " +
		"written to stdout for piping to kubectl; progress, warnings, and errors are written to stderr. The complete " +
		"render is buffered, so a failed render writes no YAML. Nothing is written to Git.",
	Args: cobra.NoArgs,
	RunE: func(cmd *cobra.Command, _ []string) error {
		if manifestsRenderFlagValues.env == "" {
			return newUsageErrorf("--env is required")
		}
		if manifestsRenderFlagValues.env != "local" {
			return newUsageErrorf("--env must be local; use 'intropy manifests create --env <environment>' for GitOps manifests")
		}
		owner, repo, err := resolveTemplateRepo(manifestsRenderFlagValues.templateRepo)
		if err != nil {
			return err
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		built, err := deploy.RenderManifests(ctx, deploy.RenderManifestOptions{
			Environment:     manifestsRenderFlagValues.env,
			System:          manifestsRenderFlagValues.system,
			TemplateVersion: manifestsRenderFlagValues.templateVersion,
			Namespace:       manifestsRenderFlagValues.namespace,
			Images:          manifestsRenderFlagValues.images,
			UserAgent:       "intropy-cli/" + version,
			Stdin:           cmd.InOrStdin(),
			Stderr:          cmd.ErrOrStderr(),
			Owner:           owner,
			Repo:            repo,
		})
		if err != nil {
			return err
		}
		n, err := cmd.OutOrStdout().Write(built)
		if err != nil {
			return fmt.Errorf("write manifests: %w", err)
		}
		if n != len(built) {
			return fmt.Errorf("write manifests: wrote %d of %d bytes", n, len(built))
		}
		return nil
	},
}

func init() {
	f := manifestsRenderCmd.Flags()
	f.StringVarP(&manifestsRenderFlagValues.env, "env", "e", "", flagUsageEnv)
	f.StringVar(&manifestsRenderFlagValues.system, "system", "", flagUsageManifestSystem)
	f.StringVar(&manifestsRenderFlagValues.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&manifestsRenderFlagValues.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.StringVar(&manifestsRenderFlagValues.namespace, "namespace", "", "target namespace (default: the system name)")
	f.StringArrayVar(&manifestsRenderFlagValues.images, "image", nil, "image override: <component>=<name:tag> for one component, :<tag> for all (repeatable)")
	_ = manifestsRenderCmd.MarkFlagRequired("env")
	manifestsCmd.AddCommand(manifestsRenderCmd)
}

