	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ManifestInspection is the environment-neutral deployment model derived from
// a system topology. Field names are stable and additive-only.
type ManifestInspection struct {
	System     string               `json:"system"`
	Template   string               `json:"template"`
	Components []InitComponent      `json:"components"`
	PubSubs    []InitPubSub         `json:"pubsubs"`
	Topics     []InitTopic          `json:"topics"`
	Connectors []InspectedConnector `json:"connectors"`
}

// InspectedConnector is one topology connector and its recorded environment
// bindings. Bindings are deployment configuration rather than topology facts.
type InspectedConnector struct {
	Name           string            `json:"name"`
	ExternalSystem string            `json:"externalSystem,omitempty"`
	Directions     []string          `json:"directions,omitempty"`
	AppIDs         []string          `json:"appIds,omitempty"`
	Bindings       map[string]string `json:"bindings,omitempty"`
}

// InspectManifestOptions configures InspectManifests.
type InspectManifestOptions struct {
	System          string
	SourceDir       string
	TopologyFile    string
	TemplateVersion string
	OutputFormat    string
	CacheRoot       string
	Runner          command.Runner
	UserAgent       string
	Stdin           io.Reader
	Stdout          io.Writer
	Stderr          io.Writer
	Owner           string
	Repo            string
	GitHubBaseURL   string
	HTTP            *http.Client
}

// RenderManifestOptions configures RenderManifests.
type RenderManifestOptions struct {
	Environment     string
	System          string
	SourceDir       string
	TopologyFile    string
	TemplateVersion string
	Namespace       string
	Images          []string
	Runner          command.Runner
	UserAgent       string
	Stdin           io.Reader
	Stderr          io.Writer
	Owner           string
	Repo            string
	GitHubBaseURL   string
	HTTP            *http.Client
}

// CreateManifestOptions configures CreateManifests.
type CreateManifestOptions struct {
	Environment     string
	Domain          string
	System          string
	SourceDir       string
	TopologyFile    string
	TemplateVersion string
	GitopsRepo      string
	DryRun          bool
	Diff            bool
	CacheRoot       string
	Runner          command.Runner
	UserAgent       string
	CliVersion      string
	Stdin           io.Reader
	Stdout          io.Writer
	Stderr          io.Writer
	Owner           string
	Repo            string
	GitHubBaseURL   string
	HTTP            *http.Client
}

// InspectManifests reports the topology and recorded deployment choices without
// rendering manifests or changing project and Git state.
func InspectManifests(ctx context.Context, opts InspectManifestOptions) error {
	initOpts := InitOptions{
		Mode:            ModeLocal,
		System:          opts.System,
		SourceDir:       opts.SourceDir,
		TopologyFile:    opts.TopologyFile,
		TemplateVersion: opts.TemplateVersion,
		OutputFormat:    opts.OutputFormat,
		CacheRoot:       opts.CacheRoot,
		Runner:          opts.Runner,
		UserAgent:       opts.UserAgent,
		Stdin:           opts.Stdin,
		Stdout:          opts.Stdout,
		Stderr:          opts.Stderr,
		Owner:           opts.Owner,
		Repo:            opts.Repo,
		GitHubBaseURL:   opts.GitHubBaseURL,
		HTTP:            opts.HTTP,
		NoInput:         true,
	}
	initOpts.applyDefaults()

	found, lib, err := prepareManifests(ctx, initOpts)
	if err != nil {
		return err
	}
	defer lib.Close()

	facts, err := newLocalInitFacts(initOpts, found)
	if err != nil {
		return err
	}
	fixtures, bindings, err := bindingCatalogs(lib)
	if err != nil {
		return err
	}
	vals, err := loadDeployValues(deployValuesPath(initOpts.SourceDir))
	if err != nil {
		return err
	}

	result := ManifestInspection{
		System:     facts.System,
		Template:   lib.Ref(),
		Components: facts.Model.Components,
		PubSubs:    facts.Model.PubSubs,
		Topics:     facts.Model.Topics,
	}
	for _, conn := range facts.Model.Connectors {
		recorded := vals.Connectors[conn.Name]
		for env, binding := range recorded {
			catalog := bindings
			if env == localEnv {
				catalog = fixtures
			}
			if len(catalog) > 0 && !slices.Contains(catalog, binding) {
				return fmt.Errorf("connector %s is bound to %q for %s, which %s does not offer; the catalog is: %s",
					conn.Name, binding, env, TemplateDeployComponent, strings.Join(catalog, ", "))
			}
		}
		result.Connectors = append(result.Connectors, InspectedConnector{
			Name:           conn.Name,
			ExternalSystem: conn.ExternalSystem,
			Directions:     conn.Directions,
			AppIDs:         conn.AppIDs,
			Bindings:       recorded,
		})
	}

	if initOpts.OutputFormat == OutputJSON {
		enc := json.NewEncoder(initOpts.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(result); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}
	return reportManifestInspection(initOpts.Stdout, result)
}

// RenderManifests builds one environment and returns its complete YAML stream.
// Returning bytes keeps stdout unreachable until every render and validation succeeds.
func RenderManifests(ctx context.Context, opts RenderManifestOptions) ([]byte, error) {
	if opts.Environment != localEnv {
		return nil, fmt.Errorf("manifest rendering supports environment %q only", localEnv)
	}
	initOpts := InitOptions{
		Mode:            ModeLocal,
		System:          opts.System,
		SourceDir:       opts.SourceDir,
		TopologyFile:    opts.TopologyFile,
		TemplateVersion: opts.TemplateVersion,
		Namespace:       opts.Namespace,
		Images:          opts.Images,
		Runner:          opts.Runner,
		UserAgent:       opts.UserAgent,
		Stdin:           opts.Stdin,
		Stderr:          opts.Stderr,
		Owner:           opts.Owner,
		Repo:            opts.Repo,
		GitHubBaseURL:   opts.GitHubBaseURL,
		HTTP:            opts.HTTP,
		NoInput:         true,
	}
	initOpts.applyDefaults()

	found, lib, err := prepareManifests(ctx, initOpts)
	if err != nil {
		return nil, err
	}
	defer lib.Close()
	return renderLocalManifests(ctx, initOpts, found, lib)
}

// CreateManifests creates missing GitOps manifest files on a review branch.
// Existing identical files are accepted; existing differing files are never replaced.
func CreateManifests(ctx context.Context, opts CreateManifestOptions) error {
