func prepareManifests(ctx context.Context, opts InitOptions) (discoveredTopology, *template.Library, error) {
	found, err := resolveInitTopology(ctx, opts)
	if err != nil {
		return discoveredTopology{}, nil, err
	}
	lib, err := template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       opts.TemplateVersion,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Stderr:        opts.Stderr,
